# -*- coding: utf-8 -*-
"""Primer lote del banco de coordinación (directivo docente coordinador).
Genera data/lotes/coord-2026-11-16.json. Todas las citas son texto literal de fuentes/."""
import json, os

RAIZ = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
casos, items = [], []


def caso(id, titulo, texto):
    casos.append({"id": id, "titulo": titulo, "texto": texto})


def item(id, caso, familia, dif, enunciado, ops, clave, explicacion, fuente, consejo, citas, competencia):
    items.append({"id": id, "tipo": "caso", "caso": caso, "familia": familia, "dificultad": dif, "enunciado": enunciado,
                  "opciones": [{"l": l, "t": t, "j": j} for l, (t, j) in zip("ABC", ops)], "clave": clave,
                  "explicacion": explicacion, "fuente": fuente, "consejo": consejo,
                  "citas": [{"doc": d, "texto": t, "ubicacion": u} for d, t, u in citas], "competencia": competencia, "cargo": "coordinador"})


G34, L715, D1075, R3842 = "guia34_mineducacion_2008", "ley_715_2001", "decreto_1075_2015", "resolucion_3842_2022_ocr"
L1620, D1965, D1421, D1278, G49, GO22 = "ley_1620_2013", "decreto_1965_2013", "decreto_1421_2017", "decreto_1278_2002", "guia49_mineducacion_2013", "guia_orientacion_cnsc_2022"

